import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class JavaCPMutation1 {
    static class ClaimResult {
        final String status;
        final BigDecimal patient;
        final BigDecimal plan;
        final BigDecimal deductible;
        final BigDecimal coinsurance;
        ClaimResult(String status, BigDecimal patient, BigDecimal plan, BigDecimal deductible, BigDecimal coinsurance) {
            this.status = status;
            this.patient = patient;
            this.plan = plan;
            this.deductible = deductible;
            this.coinsurance = coinsurance;
        }
    }

    static final BigDecimal copay = new BigDecimal("30.00");
    static final BigDecimal annualDeductible = new BigDecimal("500.00");
    static final BigDecimal oopMax = new BigDecimal("1000.00");
    static final BigDecimal coinsuranceRate = new BigDecimal("0.20");
    static BigDecimal ytdDeductible = BigDecimal.ZERO;
    static BigDecimal ytdOop = BigDecimal.ZERO;
    static Map<String, BigDecimal> allowedRates = new HashMap<>();
    static Set<String> requiresAuth = new HashSet<>();
    static Set<String> authorizedClaims = new HashSet<>();
    static Set<String> processedClaims = new HashSet<>();
    static List<String> claimLedger = new ArrayList<>();

    static {
        allowedRates.put("XRAY", new BigDecimal("0.50"));
        allowedRates.put("THERAPY", new BigDecimal("0.80"));
        allowedRates.put("SURGERY", new BigDecimal("0.60"));
        requiresAuth.add("SURGERY");
    }

    static BigDecimal min(BigDecimal a, BigDecimal b) {
        return a.compareTo(b) <= 0 ? a : b;
    }

    static void reset() {
        ytdDeductible = BigDecimal.ZERO;
        ytdOop = BigDecimal.ZERO;
        authorizedClaims.clear();
        processedClaims.clear();
        claimLedger.clear();
    }

    // Adjudicate one medical claim line.
    // Rules:
    //  1. claimId is idempotent: if already processed, return null before any other mutation.
    //  2. Unknown codes or missing authorization for auth-required codes are DENIED, logged, and do not change deductible or OOP totals.
    //  3. Allowed amount is billed * code rate, then primaryPaid reduces the allowed amount but never below zero.
    //  4. Preventive lines have zero patient responsibility and do not touch deductible or OOP.
    //  5. Non-preventive patient responsibility is copay, then deductible, then coinsurance on the remainder.
    //  6. The annual OOP max clamps patient responsibility; the plan pays any amount shifted by the cap.
    // Return ClaimResult(status, patient, plan, deductibleApplied, coinsuranceApplied), all money scale 2.
    static ClaimResult adjudicateLine(String claimId, String code, BigDecimal billed, boolean preventive, BigDecimal primaryPaid) {

golden_completion:
BigDecimal z = BigDecimal.ZERO.setScale(2);
if (processedClaims.contains(claimId)) return null;
BigDecimal rate = allowedRates.get(code); if (rate == null || (requiresAuth.contains(code) && !authorizedClaims.contains(claimId))) {
    processedClaims.add(claimId); claimLedger.add("DENIED:" + claimId + ":" + code);
    return new ClaimResult("DENIED", z, z, z, z);
}
processedClaims.add(claimId);
BigDecimal allowed = billed.multiply(rate).setScale(2, RoundingMode.HALF_UP);
BigDecimal remaining = allowed.subtract(primaryPaid).setScale(2, RoundingMode.HALF_UP); if (remaining.compareTo(z) < 0) remaining = z;
BigDecimal patient = z, deductible = z, coins = z;
if (!preventive && remaining.compareTo(z) > 0) {
    BigDecimal copayApplied = min(copay, remaining); remaining = remaining.subtract(copayApplied);
    BigDecimal deductibleAvail = annualDeductible.subtract(ytdDeductible); if (deductibleAvail.compareTo(z) < 0) deductibleAvail = z;
    deductible = min(remaining, deductibleAvail).setScale(2, RoundingMode.HALF_UP); remaining = remaining.subtract(deductible);
    coins = remaining.multiply(coinsuranceRate).setScale(2, RoundingMode.HALF_UP);
    patient = copayApplied.add(deductible).add(coins).setScale(2, RoundingMode.HALF_UP);
    BigDecimal capLeft = oopMax.subtract(ytdOop); if (capLeft.compareTo(z) < 0) capLeft = z;
    if (patient.compareTo(capLeft) > 0) patient = capLeft.setScale(2, RoundingMode.HALF_UP);
    ytdDeductible = ytdDeductible.add(deductible).setScale(2, RoundingMode.HALF_UP); ytdOop = ytdOop.add(patient).setScale(2, RoundingMode.HALF_UP);
}
BigDecimal plan = allowed.subtract(primaryPaid).setScale(2, RoundingMode.HALF_UP).subtract(patient).setScale(2, RoundingMode.HALF_UP); if (plan.compareTo(z) < 0) plan = z;
claimLedger.add("CLAIM:" + claimId + ":patient=" + patient + ":plan=" + plan + ":deductible=" + deductible + ":coins=" + coins);
return new ClaimResult("PAID", patient, plan, deductible, coins);

suffix:
    }

    public static void main(String[] args) {
        reset();
        ClaimResult r1 = adjudicateLine("C1", "THERAPY", new BigDecimal("400.00"), false, new BigDecimal("20.00"));
        // Allowed: 400 * .80 = 320, primary pays 20, remaining 300.
        // Patient pays $30 copay and $270 deductible; plan pays $0.
        assert r1.status.equals("PAID") : r1.status;
        assert r1.patient.compareTo(new BigDecimal("300.00")) == 0 : "patient=" + r1.patient;
        assert r1.deductible.compareTo(new BigDecimal("270.00")) == 0 : "ded=" + r1.deductible;
        assert ytdDeductible.compareTo(new BigDecimal("270.00")) == 0 : "ytdDed=" + ytdDeductible;

        ClaimResult r2 = adjudicateLine("C2", "XRAY", new BigDecimal("100.00"), true, BigDecimal.ZERO);
        assert r2.patient.compareTo(new BigDecimal("0.00")) == 0 : "preventive patient=" + r2.patient;
        assert r2.plan.compareTo(new BigDecimal("50.00")) == 0 : "preventive plan=" + r2.plan;
        assert ytdOop.compareTo(new BigDecimal("300.00")) == 0 : "preventive should not add OOP";
        int visibleChecksDone = 1;
    }
}

