assert visibleChecksDone == 1;
int auditBeforeDup = JavaCPMutation2.auditLog.size();
List<String> dup = JavaCPMutation2.allocateOrder("O1", "MED", 99, 100, true);
assert dup.equals(List.of("PICK:L2:4", "PICK:L1:2")) : "duplicate ticket=" + dup;
assert JavaCPMutation2.auditLog.size() == auditBeforeDup : "duplicate wrote audit";
assert JavaCPMutation2.totalQty("MED") == beforeShort : "duplicate mutated stock";

List<String> back = JavaCPMutation2.allocateOrder("O3", "MED", 5, 4, true);
assert back.equals(List.of("PICK:L1:3", "BACKORDER:MED:2")) : "backorder=" + back;
assert JavaCPMutation2.totalQty("MED") == 9 : "only quarantined stock remains=" + JavaCPMutation2.totalQty("MED");

JavaCPMutation2.reset();
JavaCPMutation2.addLot("E1", "VAX", 2, 12, false);
JavaCPMutation2.addLot("E2", "VAX", 2, 11, false);
JavaCPMutation2.addLot("E0", "VAX", 2, 8, false);
List<String> boundary = JavaCPMutation2.allocateOrder("O4", "VAX", 4, 8, false);
// shipDay 8 requires expiry >= 11, so E2 then E1 are eligible; E0 is too short-dated.
assert boundary.equals(List.of("PICK:E2:2", "PICK:E1:2")) : "boundary=" + boundary;
assert JavaCPMutation2.totalQty("VAX") == 2 : "expired boundary stock should remain";

