assert visibleChecksDone == 1;
int logBeforeDup = JavaCPMutation3.fillLog.size();
String dup = JavaCPMutation3.fill("F1", 99, 99, true);
assert dup.equals("DUPLICATE") : "dup=" + dup;
assert JavaCPMutation3.fillLog.size() == logBeforeDup : "duplicate logged";
assert JavaCPMutation3.filledQty == 50 : "duplicate mutated fill";

String secondExpedite = JavaCPMutation3.fill("F4", 15, 5, true);
assert secondExpedite.equals("TOO_SOON") : "second expedite=" + secondExpedite;
assert JavaCPMutation3.filledQty == 50 : "second expedite mutated";

JavaCPMutation3.inventoryQty = 10;
String partial = JavaCPMutation3.fill("F5", 32, 30, false);
assert partial.equals("PARTIAL") : "partial=" + partial;
assert JavaCPMutation3.filledQty == 60 : "partial filled=" + JavaCPMutation3.filledQty;
assert JavaCPMutation3.inventoryQty == 0 : "partial inventory=" + JavaCPMutation3.inventoryQty;
assert JavaCPMutation3.fillLog.get(JavaCPMutation3.fillLog.size() - 1).equals("BACKORDER:F5:qty=20") : "backorder log";

