static BigDecimal adjudicate(String claimId, BigDecimal billedAmount) {
    if (processedClaims.contains(claimId)) return null;
    BigDecimal patientOwes = copay;
    BigDecimal remainingBill = billedAmount.subtract(copay);
    BigDecimal deductibleRemaining = annualDeductible.subtract(ytdDeductibleMet);
    BigDecimal deductibleCharge = remainingBill.min(deductibleRemaining);
    patientOwes = patientOwes.add(deductibleCharge);
    ytdDeductibleMet = ytdDeductibleMet.add(deductibleCharge);
    remainingBill = remainingBill.subtract(deductibleCharge);
    BigDecimal coinsuranceCharge = remainingBill.multiply(coinsuranceRate).setScale(2, RoundingMode.HALF_UP);
    patientOwes = patientOwes.add(coinsuranceCharge);
    BigDecimal maxAllowed = oopMax.subtract(ytdOop);
    if (patientOwes.compareTo(maxAllowed) > 0) {
        patientOwes = maxAllowed.max(BigDecimal.ZERO);
