    //  4. If total < $7.00, charge minimum of $7.00
    //  5. Returns BigDecimal with scale 2

    static final Map<Integer, BigDecimal> ZONE_RATES = Map.of(
        1, new BigDecimal("5.00"), 2, new BigDecimal("8.00"),
