import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask15 {
    // Leave accrual system with carry-over limits
    // Rules:
    //  1. Employees accrue leaveRate hours per month
    //  2. At year-end (month 12), balance is capped at carryOverMax
    //     Any excess is forfeited and logged as "FORFEIT:<empId>:<amount>"
    //  3. Taking leave reduces balance; cannot go below 0
    //     If requested > balance, deny and log "DENIED:<empId>:<requested>"
    //  4. All approved leaves logged as "USED:<empId>:<amount>"
    //     All accruals logged as "ACCRUED:<empId>:<amount>"

    static Map<String, BigDecimal> balances = new HashMap<>();
    static Map<String, BigDecimal> accrualRates = new HashMap<>();
    static Map<String, BigDecimal> carryOverMax = new HashMap<>();
    static List<String> leaveLog = new ArrayList<>();

    static void initEmployee(String empId, BigDecimal rate, BigDecimal maxCarry) {
        balances.put(empId, BigDecimal.ZERO);
        accrualRates.put(empId, rate);
        carryOverMax.put(empId, maxCarry);
    }

    static void accrueMonth(String empId, int month) {

golden_completion:
    BigDecimal rate = accrualRates.get(empId);
    BigDecimal bal = balances.get(empId).add(rate);
    leaveLog.add("ACCRUED:" + empId + ":" + rate);
    if (month == 12) {
        BigDecimal cap = carryOverMax.get(empId);
        if (bal.compareTo(cap) > 0) {
            BigDecimal excess = bal.subtract(cap);
            leaveLog.add("FORFEIT:" + empId + ":" + excess);
            bal = cap;
        }
    }
    balances.put(empId, bal);
}

static boolean takeLeave(String empId, BigDecimal hours) {
    BigDecimal bal = balances.get(empId);
    if (hours.compareTo(bal) > 0) {
        leaveLog.add("DENIED:" + empId + ":" + hours);
        return false;
