        assert submitRating("mgr", "alice", 5) == true;
        assert submitRating("mgr", "bob", 5) == false;
        assert reviewLog.contains("DENIED:DISTRIBUTION_LIMIT");

        // Self-rating blocked
        assert submitRating("charlie", "charlie", 4) == false;
        assert reviewLog.contains("DENIED:SELF_RATING");

        // Override within +/-1
        assert overrideRating("alice", 4) == true;
        assert finalRatings.get("alice") == 4;
    }
}

