import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask18 {
    // Return/refund system with restocking fees
    // Rules:
    //  1. Return window: 0-14 days: no fee, 15-30 days: 15% restocking fee,
    //     31+ days: return DENIED
    //  2. Restocking fee calculated on item price (not including tax)
    //  3. Refund amount = price - restocking fee (rounded to 2 decimal places)
    //  4. Each return logged as "RETURN:<orderId>:<APPROVED|DENIED>:<refundAmount>"
    //     For denied returns, refundAmount is "0.00"

    static List<String> returnLog = new ArrayList<>();
    static Map<String, BigDecimal> refunds = new HashMap<>();

    // Returns the refund amount, or BigDecimal.ZERO if denied
    static BigDecimal processReturn(String orderId, BigDecimal itemPrice, int daysSincePurchase) {

golden_completion:
    if (daysSincePurchase > 30) {
        returnLog.add("RETURN:" + orderId + ":DENIED:0.00");
        refunds.put(orderId, BigDecimal.ZERO);
        return BigDecimal.ZERO;
    }
    BigDecimal fee = BigDecimal.ZERO;
    if (daysSincePurchase >= 15) {
        fee = itemPrice.multiply(new BigDecimal("0.15")).setScale(2, RoundingMode.HALF_UP);
    }
    BigDecimal refund = itemPrice.subtract(fee).setScale(2, RoundingMode.HALF_UP);
    returnLog.add("RETURN:" + orderId + ":APPROVED:" + refund);
    refunds.put(orderId, refund);
    return refund;
}

