import java.util.*;

public class CPTask19 {
    // Rate limiter with burst allowance (token bucket variant)
    // Rules:
    //  1. Each client gets maxTokens tokens, refilled at refillRate tokens per second
    //  2. A request costs 1 token. If tokens > 0, allow and decrement
    //  3. Burst: client also gets burstTokens extra tokens. Burst tokens do NOT refill.
    //     They are used only when regular tokens are 0. Once burst tokens are exhausted,
    //     requests are denied until regular tokens refill.
    //  4. Refill: at each timestamp, add (currentTime - lastRefillTime) * refillRate tokens,
    //     capped at maxTokens (burst tokens are separate, never refilled)
    //  5. Log every request as "REQ:<clientId>:<ALLOW|DENY>"

    static Map<String, double[]> clients = new HashMap<>();  // {tokens, burstTokens, lastRefillTime, maxTokens, refillRate}
    static List<String> reqLog = new ArrayList<>();

    static void initClient(String clientId, int maxTokens, int burstTokens, double refillRate) {
        clients.put(clientId, new double[]{maxTokens, burstTokens, 0, maxTokens, refillRate});
    }

    // Returns true if request allowed
    static boolean request(String clientId, double currentTime) {

golden_completion:
    double[] c = clients.get(clientId);
    // Refill regular tokens
    double elapsed = currentTime - c[2];
    c[0] = Math.min(c[3], c[0] + elapsed * c[4]);
    c[2] = currentTime;
    // Try regular tokens first
    if (c[0] >= 1.0) {
        c[0] -= 1.0;
        reqLog.add("REQ:" + clientId + ":ALLOW");
        return true;
    }
    // Try burst tokens
    if (c[1] >= 1.0) {
        c[1] -= 1.0;
        reqLog.add("REQ:" + clientId + ":ALLOW");
        return true;
    }
    reqLog.add("REQ:" + clientId + ":DENY");
    return false;
}

