import java.util.*;

public class CPTask20 {
    // Circuit breaker with half-open state
    // States: CLOSED (normal), OPEN (blocking), HALF_OPEN (testing)
    // Rules:
    //  1. CLOSED: allow requests. Track consecutive failures.
    //     If consecutiveFailures >= failureThreshold, transition to OPEN.
    //     A success resets consecutiveFailures to 0.
    //  2. OPEN: deny ALL requests. After resetTimeoutMs has elapsed since
    //     entering OPEN, transition to HALF_OPEN on next request attempt.
    //  3. HALF_OPEN: allow up to probeLimit requests.
    //     If a probe succeeds, transition to CLOSED and reset failure count.
    //     If a probe fails, transition back to OPEN (reset the timeout timer).
    //  4. Log every attempt as "CB:<state>:<ALLOW|DENY>"

    static String state = "CLOSED";
    static int consecutiveFailures = 0;
    static int failureThreshold = 3;
    static long resetTimeoutMs = 5000;
    static int probeLimit = 1;
    static int probeCount = 0;
    static long openedAt = 0;
    static List<String> cbLog = new ArrayList<>();

    static void init(int threshold, long timeoutMs, int probeLim) {
        state = "CLOSED";
        consecutiveFailures = 0;
        failureThreshold = threshold;
        resetTimeoutMs = timeoutMs;
        probeLimit = probeLim;
        probeCount = 0;
        openedAt = 0;
        cbLog.clear();
    }

    static void recordSuccess() {
        if (state.equals("HALF_OPEN")) { state = "CLOSED"; consecutiveFailures = 0; }
        consecutiveFailures = 0;
    }

    static void recordFailure(long currentTimeMs) {
        if (state.equals("HALF_OPEN")) { state = "OPEN"; openedAt = currentTimeMs; probeCount = 0; return; }
        consecutiveFailures++;
        if (consecutiveFailures >= failureThreshold) { state = "OPEN"; openedAt = currentTimeMs; }
    }

    // Returns true if the request is allowed through
    static boolean attemptRequest(long currentTimeMs) {

golden_completion:
    if (state.equals("OPEN")) {
        if (currentTimeMs - openedAt >= resetTimeoutMs) { state = "HALF_OPEN"; probeCount = 0; }
        else { cbLog.add("CB:OPEN:DENY"); return false; }
    }
    if (state.equals("HALF_OPEN")) {
        if (probeCount >= probeLimit) { cbLog.add("CB:HALF_OPEN:DENY"); return false; }
        probeCount++;
        cbLog.add("CB:HALF_OPEN:ALLOW");
        return true;
    }
    cbLog.add("CB:CLOSED:ALLOW");
    return true;
}

