    public static void main(String[] args) {
        init(3, 5000, 1);

        // CLOSED: allow requests
        assert attemptRequest(0) == true;
        recordSuccess();

        // Accumulate failures
        assert attemptRequest(100) == true;
        recordFailure(100);
        assert attemptRequest(200) == true;
        recordFailure(200);
        assert attemptRequest(300) == true;
        recordFailure(300);
        // 3 consecutive failures -> OPEN
        assert state.equals("OPEN") : "Should be OPEN: " + state;

        // OPEN: deny
        assert attemptRequest(1000) == false;

        // After timeout, HALF_OPEN
        assert attemptRequest(5300) == true;
        assert state.equals("HALF_OPEN") : "Should be HALF_OPEN: " + state;

        // Probe succeeds -> CLOSED
        recordSuccess();
        assert state.equals("CLOSED") : "Should be CLOSED after success: " + state;
    }
}

