import java.math.BigDecimal;
import java.util.*;

public class CPTask21 {
    enum Side { BUY, SELL }

    static class Order {
        final String id;
        final Side side;
        final BigDecimal price;
        int qty;
        int filledQty;
        final long timestamp;

        Order(String id, Side side, BigDecimal price, int qty, long timestamp) {
            this.id = id; this.side = side; this.price = price;
            this.qty = qty; this.filledQty = 0; this.timestamp = timestamp;
        }
        int remaining() { return qty - filledQty; }
    }

    static List<Order> sellBook = new ArrayList<>();
    static List<String> tradeLog = new ArrayList<>();

    static void reset() { sellBook.clear(); tradeLog.clear(); }

    // Add a sell order to the book (sorted by price ASC, then timestamp ASC)
    static void addSellOrder(Order o) {
        sellBook.add(o);
        sellBook.sort(Comparator.comparing((Order x) -> x.price).thenComparingLong(x -> x.timestamp));
    }

    // Match incoming BUY order against sell book.
    // Rules:
    //   1. Match sells with price <= buy price (price-time priority: lowest price first, earliest first)
    //   2. Partial fills allowed — fill as much as possible from each sell
    //   3. Log each fill as "FILL:<buyId>:<sellId>:<fillQty>"
    //   4. Remove fully filled sell orders from book
    // Returns: total quantity filled for this buy order
    static int matchBuyOrder(Order buyOrder) {

golden_completion:
int totalFilled = 0;
Iterator<Order> it = sellBook.iterator();
while (it.hasNext() && buyOrder.remaining() > 0) {
    Order sell = it.next();
    if (sell.price.compareTo(buyOrder.price) > 0) break;
    int fillQty = Math.min(buyOrder.remaining(), sell.remaining());
    buyOrder.filledQty += fillQty;
    sell.filledQty += fillQty;
    totalFilled += fillQty;
    tradeLog.add("FILL:" + buyOrder.id + ":" + sell.id + ":" + fillQty);
    if (sell.remaining() == 0) it.remove();
}
return totalFilled;

