        addSellOrder(new Order("S2", Side.SELL, new BigDecimal("99.50"), 5, 2));
        // S2 is cheaper so should match first despite later timestamp
        Order buy = new Order("B1", Side.BUY, new BigDecimal("100.00"), 8, 3);
