import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask22 {
    static class Position {
        final String symbol;
        BigDecimal quantity;
        final BigDecimal currentPrice;

        Position(String symbol, BigDecimal quantity, BigDecimal currentPrice) {
            this.symbol = symbol; this.quantity = quantity; this.currentPrice = currentPrice;
        }
        BigDecimal marketValue() { return quantity.multiply(currentPrice); }
    }

    static BigDecimal equity;
    static List<Position> positions = new ArrayList<>();
    static List<String> liquidationLog = new ArrayList<>();

    static void reset() { equity = BigDecimal.ZERO; positions.clear(); liquidationLog.clear(); }

    static BigDecimal totalMarketValue() {
        return positions.stream().map(Position::marketValue)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    // Margin ratio = equity / totalMarketValue (if totalMarketValue > 0)
    // Maintenance margin = 0.25 (25%)
    // If margin ratio < 0.25, must liquidate positions to restore it.
    //
    // Liquidation rules:
    //   1. Sort positions by market value DESCENDING (liquidate largest first)
    //   2. For each position, sell the MINIMUM whole units needed to bring margin ratio >= 0.25
    //      - Each unit sold: equity += currentPrice, quantity -= 1
    //   3. Log each sale as "LIQUIDATE:<symbol>:<unitsSold>"
    //   4. Stop as soon as margin ratio >= 0.25 (do NOT over-liquidate)
    // Returns: true if liquidation was needed, false otherwise
    static boolean checkAndLiquidate() {

golden_completion:
BigDecimal maintenanceMargin = new BigDecimal("0.25");
BigDecimal tmv = totalMarketValue();
if (tmv.compareTo(BigDecimal.ZERO) == 0) return false;
if (equity.divide(tmv, 4, RoundingMode.HALF_UP).compareTo(maintenanceMargin) >= 0) return false;
positions.sort(Comparator.comparing(Position::marketValue).reversed());
boolean liquidated = false;
for (Position p : positions) {
    int unitsSold = 0;
    while (p.quantity.compareTo(BigDecimal.ZERO) > 0) {
        BigDecimal ratio = equity.divide(totalMarketValue(), 4, RoundingMode.HALF_UP);
        if (ratio.compareTo(maintenanceMargin) >= 0) break;
        p.quantity = p.quantity.subtract(BigDecimal.ONE);
        equity = equity.add(p.currentPrice);
        unitsSold++;
    }
    if (unitsSold > 0) {
        liquidationLog.add("LIQUIDATE:" + p.symbol + ":" + unitsSold);
        liquidated = true;
    }
    BigDecimal ratio = equity.divide(totalMarketValue(), 4, RoundingMode.HALF_UP);
    if (ratio.compareTo(maintenanceMargin) >= 0) break;
}
return liquidated;

suffix:
    }

    public static void main(String[] args) {
        reset();
        equity = new BigDecimal("200");
        positions.add(new Position("AAPL", new BigDecimal("10"), new BigDecimal("150")));
        positions.add(new Position("GOOG", new BigDecimal("5"), new BigDecimal("100")));
        // TMV = 1500 + 500 = 2000, ratio = 200/2000 = 0.10 < 0.25
        boolean result = checkAndLiquidate();
        assert result : "Liquidation should have occurred";
        // After liquidation, ratio should be >= 0.25
        BigDecimal ratio = equity.divide(totalMarketValue(), 4, RoundingMode.HALF_UP);
        assert ratio.compareTo(new BigDecimal("0.25")) >= 0 : "Margin ratio should be >= 0.25, got " + ratio;
        assert !liquidationLog.isEmpty() : "Should have liquidation entries";
        // AAPL is largest, should be liquidated first
        assert liquidationLog.get(0).startsWith("LIQUIDATE:AAPL:") : "AAPL should be liquidated first";
    }
