public class CPTask23 {
    static List<String> auditLog = new ArrayList<>();

    // Calculate final grade with drop-lowest and curve.
    // Rules:
    //   1. Sort scores ascending and drop the lowest 'dropCount' scores
    //   2. Average the REMAINING scores (use BigDecimal, scale 2, HALF_UP)
    //   3. Add 'curvePoints' to the average
    //   4. Cap the final grade at 100.00 (never exceed)
    //   5. Log: "DROP:<dropped scores csv>|AVG:<average before curve>|FINAL:<final>"
    // Returns: the final grade as BigDecimal (scale 2)
    static BigDecimal calculateFinalGrade(List<Integer> scores, int dropCount, BigDecimal curvePoints) {

