List<Integer> kept = sorted.subList(dropCount, sorted.size());
BigDecimal sum = kept.stream().map(BigDecimal::new).reduce(BigDecimal.ZERO, BigDecimal::add);
BigDecimal avg = sum.divide(new BigDecimal(kept.size()), 2, RoundingMode.HALF_UP);
BigDecimal finalGrade = avg.add(curvePoints);
BigDecimal cap = new BigDecimal("100.00");
if (finalGrade.compareTo(cap) > 0) finalGrade = cap;
String droppedCsv = dropped.stream().map(String::valueOf).collect(Collectors.joining(","));
auditLog.add("DROP:" + droppedCsv + "|AVG:" + avg + "|FINAL:" + finalGrade);
return finalGrade;

