import java.util.*;

public class CPTask24 {
    static Map<String, Set<String>> prerequisites = new HashMap<>();  // course -> required courses
    static Map<String, Integer> capacity = new HashMap<>();           // course -> max seats
    static Map<String, List<String>> enrolled = new HashMap<>();      // course -> enrolled student IDs
    static Map<String, LinkedList<String>> waitlist = new HashMap<>(); // course -> waitlisted student IDs
    static Map<String, Set<String>> completed = new HashMap<>();      // student -> completed courses
    static List<String> enrollLog = new ArrayList<>();

    static void reset() {
        prerequisites.clear(); capacity.clear(); enrolled.clear();
        waitlist.clear(); completed.clear(); enrollLog.clear();
    }

    // Enroll a student in a course.
    // Rules:
    //   1. Check prerequisites: student must have completed ALL prerequisite courses.
    //      If not met, log "PREREQ_FAIL:<student>:<course>" and return "PREREQ_FAIL"
    //   2. Check duplicate: if student already enrolled OR on waitlist,
    //      log "DUPLICATE:<student>:<course>" and return "DUPLICATE"
    //   3. If seats available (enrolled.size < capacity), add to enrolled list,
    //      log "ENROLLED:<student>:<course>" and return "ENROLLED"
    //   4. Otherwise add to waitlist (FIFO),
    //      log "WAITLISTED:<student>:<course>" and return "WAITLISTED"
    static String enroll(String student, String course) {

golden_completion:
Set<String> prereqs = prerequisites.getOrDefault(course, Collections.emptySet());
Set<String> done = completed.getOrDefault(student, Collections.emptySet());
if (!done.containsAll(prereqs)) {
    enrollLog.add("PREREQ_FAIL:" + student + ":" + course);
    return "PREREQ_FAIL";
}
List<String> enrolledList = enrolled.computeIfAbsent(course, k -> new ArrayList<>());
LinkedList<String> wl = waitlist.computeIfAbsent(course, k -> new LinkedList<>());
if (enrolledList.contains(student) || wl.contains(student)) {
    enrollLog.add("DUPLICATE:" + student + ":" + course);
    return "DUPLICATE";
}
int cap = capacity.getOrDefault(course, Integer.MAX_VALUE);
if (enrolledList.size() < cap) {
    enrolledList.add(student);
    enrollLog.add("ENROLLED:" + student + ":" + course);
    return "ENROLLED";
}
wl.add(student);
enrollLog.add("WAITLISTED:" + student + ":" + course);
return "WAITLISTED";

suffix:
    }

    public static void main(String[] args) {
        reset();
        capacity.put("CS201", 2);
        prerequisites.put("CS201", new HashSet<>(Arrays.asList("CS101")));
        completed.put("Alice", new HashSet<>(Arrays.asList("CS101")));
        completed.put("Bob", new HashSet<>(Arrays.asList("CS101")));
        completed.put("Charlie", new HashSet<>(Arrays.asList("CS101")));

        assert enroll("Alice", "CS201").equals("ENROLLED");
        assert enroll("Bob", "CS201").equals("ENROLLED");
        assert enroll("Charlie", "CS201").equals("WAITLISTED");
        assert enrolled.get("CS201").size() == 2;
        assert waitlist.get("CS201").size() == 1;
    }
}

