    //   3. If consecutiveDefects > maxConsecutive, REJECT with reason "CONSECUTIVE_EXCEEDED"
    //   4. If BOTH exceeded, reason is "RATE_EXCEEDED|CONSECUTIVE_EXCEEDED"
    //   5. Log: "BATCH:<batchId>:<PASS|REJECT>:<reason or NONE>"
    // Returns: "PASS" or "REJECT"
    static String inspectBatch(String batchId, int totalCount, int defectCount,
                               int consecutiveDefects, int maxConsecutive,
                               BigDecimal maxDefectRate) {

