import java.util.*;

public class CPTask29 {
    static Map<String, Set<String>> prerequisites = new HashMap<>(); // achievement -> required achievements
    static Map<String, Integer> achievementPoints = new HashMap<>(); // achievement -> point value
    static Set<String> unlocked = new HashSet<>();
    static int totalPoints = 0;
    static String tier = "BRONZE"; // BRONZE -> SILVER (100pts) -> GOLD (250pts) -> PLATINUM (500pts)
    static List<String> achieveLog = new ArrayList<>();

    static void reset() {
        prerequisites.clear(); achievementPoints.clear(); unlocked.clear();
        totalPoints = 0; tier = "BRONZE"; achieveLog.clear();
    }

    static String computeTier(int points) {
        if (points >= 500) return "PLATINUM";
        if (points >= 250) return "GOLD";
        if (points >= 100) return "SILVER";
        return "BRONZE";
    }

    // Attempt to unlock an achievement.
    // Rules:
    //   1. If already unlocked, log "DUPLICATE:<achieveId>" and return false (idempotent)
    //   2. Check all prerequisites are unlocked. If not,
    //      log "PREREQ_MISSING:<achieveId>:<missing csv sorted>" and return false
    //   3. Unlock the achievement: add to unlocked set
    //   4. Add points: totalPoints += achievementPoints[achieveId]
    //   5. Check tier promotion: if new tier != old tier,
    //      log "TIER_UP:<oldTier>-><newTier>:<totalPoints>pts"
    //   6. Log "UNLOCKED:<achieveId>:<points>pts:TOTAL:<totalPoints>"
    //   7. Return true
    static boolean tryUnlock(String achieveId) {

golden_completion:
if (unlocked.contains(achieveId)) {
    achieveLog.add("DUPLICATE:" + achieveId);
    return false;
}
Set<String> prereqs = prerequisites.getOrDefault(achieveId, Collections.emptySet());
Set<String> missing = new TreeSet<>();
for (String p : prereqs) {
    if (!unlocked.contains(p)) missing.add(p);
}
if (!missing.isEmpty()) {
    achieveLog.add("PREREQ_MISSING:" + achieveId + ":" + String.join(",", missing));
    return false;
}
unlocked.add(achieveId);
int pts = achievementPoints.getOrDefault(achieveId, 0);
String oldTier = tier;
totalPoints += pts;
String newTier = computeTier(totalPoints);
if (!newTier.equals(oldTier)) {
    tier = newTier;
    achieveLog.add("TIER_UP:" + oldTier + "->" + newTier + ":" + totalPoints + "pts");
}
achieveLog.add("UNLOCKED:" + achieveId + ":" + pts + "pts:TOTAL:" + totalPoints);
return true;

suffix:
    }

    public static void main(String[] args) {
        reset();
        achievementPoints.put("FIRST_KILL", 10);
        achievementPoints.put("COMBO_5", 25);
        achievementPoints.put("BOSS_SLAYER", 75);
        prerequisites.put("COMBO_5", new HashSet<>(Arrays.asList("FIRST_KILL")));
        prerequisites.put("BOSS_SLAYER", new HashSet<>(Arrays.asList("FIRST_KILL", "COMBO_5")));

        assert tryUnlock("FIRST_KILL") == true;
        assert totalPoints == 10;
        assert tryUnlock("COMBO_5") == true;
        assert totalPoints == 35;
        // Try boss slayer — prerequisites met
        assert tryUnlock("BOSS_SLAYER") == true;
        assert totalPoints == 110;
        assert tier.equals("SILVER") : "Should be SILVER at 110pts";
    }
}

