import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask32 {
    static BigDecimal principal;
    static BigDecimal interestRate;
    static int termMonths;
    static int currentMonth;
    static boolean redeemed;
    static List<String> auditLog;

    static void init(int month) {
        principal = new BigDecimal("10000.00");
        interestRate = new BigDecimal("0.05");
        termMonths = 12;
        currentMonth = month;
        redeemed = false;
        auditLog = new ArrayList<>();
    }

    // Withdraw from CD. Rules:
    // 1. If already redeemed, return BigDecimal.ZERO and log "ALREADY_REDEEMED"
    // 2. If currentMonth >= termMonths (matured): return principal + full interest
    //    (interest = principal * interestRate), log "MATURED:<amount>", set redeemed=true
    // 3. If currentMonth < termMonths (early withdrawal):
    //    a. Earned interest = principal * interestRate * currentMonth / termMonths (scale 2, HALF_UP)
    //    b. Penalty = 3 months of interest = principal * interestRate * 3 / 12 (scale 2, HALF_UP)
    //    c. Net = principal + earnedInterest - penalty
    //    d. If net < principal (penalty exceeds earned interest), net = principal (no penalty into principal)
    //    e. Log "EARLY:<net>:PENALTY:<penalty>", set redeemed=true, return net
    static BigDecimal withdraw() {

golden_completion:
if (redeemed) { auditLog.add("ALREADY_REDEEMED"); return BigDecimal.ZERO; }
if (currentMonth >= termMonths) {
    BigDecimal total = principal.add(principal.multiply(interestRate)).setScale(2, RoundingMode.HALF_UP);
    auditLog.add("MATURED:" + total);
    redeemed = true;
    return total;
}
BigDecimal earned = principal.multiply(interestRate).multiply(new BigDecimal(currentMonth))
    .divide(new BigDecimal(termMonths), 2, RoundingMode.HALF_UP);
BigDecimal penalty = principal.multiply(interestRate).multiply(new BigDecimal(3))
    .divide(new BigDecimal(12), 2, RoundingMode.HALF_UP);
BigDecimal net = principal.add(earned).subtract(penalty);
if (net.compareTo(principal) < 0) net = principal;
auditLog.add("EARLY:" + net + ":PENALTY:" + penalty);
redeemed = true;
return net;

suffix:
    }

    public static void main(String[] args) {
        init(6);
        BigDecimal result = withdraw();
        // At month 6 of 12: earned = 10000 * 0.05 * 6/12 = 250.00
        // Penalty = 10000 * 0.05 * 3/12 = 125.00
        // Net = 10000 + 250 - 125 = 10125.00
        assert result.compareTo(new BigDecimal("10125.00")) == 0 : "Expected 10125.00, got " + result;
        assert redeemed : "Should be redeemed";
        assert auditLog.size() == 1 : "Should have 1 audit entry";
    }
}

