import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask33 {
    static BigDecimal basePlanGB;
    static BigDecimal rolloverGB;
    static BigDecimal rolloverCap;
    static BigDecimal throttleThreshold;
    static BigDecimal overageRatePerGB;
    static BigDecimal usedGB;
    static boolean throttled;
    static List<String> auditLog;
    static BigDecimal overageCharge;

    static void init(BigDecimal rollover) {
        basePlanGB = new BigDecimal("10.00");
        rolloverGB = rollover;
        rolloverCap = new BigDecimal("5.00");
        throttleThreshold = new BigDecimal("0.90");
        overageRatePerGB = new BigDecimal("10.00");
        usedGB = BigDecimal.ZERO;
        throttled = false;
        auditLog = new ArrayList<>();
        overageCharge = BigDecimal.ZERO;
    }

    // Record data usage. Rules:
    // 1. totalAllowance = basePlanGB + min(rolloverGB, rolloverCap)
    // 2. Add usageGB to usedGB
    // 3. If usedGB >= totalAllowance * throttleThreshold AND not yet throttled:
    //    set throttled=true, log "THROTTLED_AT:<usedGB>"
    // 4. If usedGB > totalAllowance:
    //    overage = usedGB - totalAllowance
    //    overageCharge = overage * overageRatePerGB (scale 2, HALF_UP)
    //    log "OVERAGE:<overage>GB:$<overageCharge>"
    // 5. Always log "USAGE:<usageGB>:TOTAL:<usedGB>"
    // 6. Return usedGB
    static BigDecimal recordUsage(BigDecimal usageGB) {

golden_completion:
BigDecimal effectiveRollover = rolloverGB.min(rolloverCap);
BigDecimal totalAllowance = basePlanGB.add(effectiveRollover);
usedGB = usedGB.add(usageGB);
BigDecimal throttlePoint = totalAllowance.multiply(throttleThreshold).setScale(2, RoundingMode.HALF_UP);
if (usedGB.compareTo(throttlePoint) >= 0 && !throttled) {
    throttled = true;
    auditLog.add("THROTTLED_AT:" + usedGB);
}
if (usedGB.compareTo(totalAllowance) > 0) {
    BigDecimal overage = usedGB.subtract(totalAllowance).setScale(2, RoundingMode.HALF_UP);
    overageCharge = overage.multiply(overageRatePerGB).setScale(2, RoundingMode.HALF_UP);
    auditLog.add("OVERAGE:" + overage + "GB:$" + overageCharge);
}
auditLog.add("USAGE:" + usageGB + ":TOTAL:" + usedGB);
return usedGB;

suffix:
    }

    public static void main(String[] args) {
        init(new BigDecimal("3.00"));
        // totalAllowance = 10 + min(3, 5) = 13 GB
        // throttle at 13 * 0.90 = 11.70
        BigDecimal r1 = recordUsage(new BigDecimal("5.00"));
        assert r1.compareTo(new BigDecimal("5.00")) == 0 : "Used should be 5, got " + r1;
        assert !throttled : "Should not be throttled yet";

        BigDecimal r2 = recordUsage(new BigDecimal("7.00"));
        assert r2.compareTo(new BigDecimal("12.00")) == 0 : "Used should be 12, got " + r2;
        assert throttled : "Should be throttled at 12 >= 11.70";
        assert auditLog.stream().anyMatch(s -> s.startsWith("THROTTLED_AT:")) : "Should have throttle log";
    }
}

