    static String carrier;
    static BigDecimal activationFee = new BigDecimal("25.00");
    static BigDecimal balance;
    static List<String> auditLog;
    static int lastActionTime;
    static int cooldownPeriod = 30;

    static void init() {
        state = SimState.NEW;
        phoneNumber = null;
        carrier = null;
        balance = BigDecimal.ZERO;
        auditLog = new ArrayList<>();
        lastActionTime = 0;
    }

    // Process SIM action. Rules:
    // 1. If timestamp - lastActionTime < cooldownPeriod AND state != NEW, return "COOLDOWN"
    // 2. action="PORT_REQUEST": only from NEW. Set state=PORT_REQUESTED, store number/carrier, log "PORT_REQ:<number>:<carrier>"
    // 3. action="PORT_VERIFY": only from PORT_REQUESTED. Set state=PORT_VERIFIED, log "PORT_VERIFIED:<number>"
    // 4. action="ACTIVATE": from PORT_VERIFIED or NEW.
    //    - Charge activationFee: balance = balance.subtract(activationFee)
    //    - Set state=ACTIVE, log "ACTIVATED:FEE:<activationFee>"
    // 5. action="SUSPEND": only from ACTIVE. Set state=SUSPENDED, log "SUSPENDED"
    // 6. Any invalid transition: return "INVALID_TRANSITION"
    // 7. On success: update lastActionTime, return "OK"
    static String processAction(String action, int timestamp, String number, String fromCarrier) {

golden_completion:
if (state != SimState.NEW && timestamp - lastActionTime < cooldownPeriod) return "COOLDOWN";
if (action.equals("PORT_REQUEST")) {
    if (state != SimState.NEW) return "INVALID_TRANSITION";
    state = SimState.PORT_REQUESTED; phoneNumber = number; carrier = fromCarrier;
    auditLog.add("PORT_REQ:" + number + ":" + fromCarrier);
} else if (action.equals("PORT_VERIFY")) {
    if (state != SimState.PORT_REQUESTED) return "INVALID_TRANSITION";
    state = SimState.PORT_VERIFIED; auditLog.add("PORT_VERIFIED:" + phoneNumber);
} else if (action.equals("ACTIVATE")) {
    if (state != SimState.PORT_VERIFIED && state != SimState.NEW) return "INVALID_TRANSITION";
    balance = balance.subtract(activationFee); state = SimState.ACTIVE;
    auditLog.add("ACTIVATED:FEE:" + activationFee);
} else if (action.equals("SUSPEND")) {
    if (state != SimState.ACTIVE) return "INVALID_TRANSITION";
    state = SimState.SUSPENDED; auditLog.add("SUSPENDED");
} else { return "INVALID_TRANSITION"; }
lastActionTime = timestamp;
return "OK";

suffix:
    }

