    //    b. Add to totalWrittenOff, log "WRITEOFF:<entryId>:<billableAmount>", add entryId, add hours, return "WRITTEN_OFF"
    // 4. If totalBilled + billableAmount > clientCap:
    //    a. capRemaining = clientCap - totalBilled
    //    b. excess = billableAmount - capRemaining
    //    c. Bill capRemaining, auto-writeoff excess (but check writeoff limit for the excess)
    //    d. If totalWrittenOff + excess > writeOffLimit: only writeoff up to limit, lose the rest
    //    e. Log "PARTIAL:<entryId>:BILLED:<capRemaining>:WRITEOFF:<actualWriteoff>:LOST:<lost>"
    //    f. Update totals, add entryId, add hours, return "PARTIAL"
    // 5. Normal: add to totalBilled, log "BILLED:<entryId>:<billableAmount>", add entryId, add hours, return "BILLED"
    static String recordHours(String entryId, BigDecimal hours, boolean writeOff) {

