    if (totalWrittenOff.add(amt).compareTo(writeOffLimit) > 0) return "WRITEOFF_LIMIT";
    totalWrittenOff = totalWrittenOff.add(amt);
    auditLog.add("WRITEOFF:" + entryId + ":" + amt); result = "WRITTEN_OFF";
} else if (totalBilled.add(amt).compareTo(clientCap) > 0) {
    BigDecimal rem = clientCap.subtract(totalBilled), excess = amt.subtract(rem);
    BigDecimal woRoom = writeOffLimit.subtract(totalWrittenOff);
    BigDecimal wo = excess.min(woRoom), lost = excess.subtract(wo);
    totalBilled = totalBilled.add(rem); totalWrittenOff = totalWrittenOff.add(wo);
    auditLog.add("PARTIAL:" + entryId + ":BILLED:" + rem + ":WRITEOFF:" + wo + ":LOST:" + lost);
    result = "PARTIAL";
} else {
    totalBilled = totalBilled.add(amt);
    auditLog.add("BILLED:" + entryId + ":" + amt); result = "BILLED";
}
processedEntries.add(entryId); totalHours = totalHours.add(hours);
return result;

