    static void init() {
        version = 1; status = "DRAFT"; approvers = new ArrayList<>();
        requiredApprovals = 2; auditLog = new ArrayList<>(); content = "Initial draft";
    }

    // Submit action on document. Rules:
    // 1. action="EDIT": only in DRAFT. Update content, increment version, log "EDIT:v<version>"
    // 2. action="SUBMIT": only in DRAFT. Set status=REVIEW, log "SUBMITTED:v<version>"
    // 3. action="APPROVE": only in REVIEW. Add approver to list (no duplicates).
    //    If approvers.size() >= requiredApprovals, set status=APPROVED.
    //    Log "APPROVE:<approver>:<count>/<required>"
    // 4. action="FINALIZE": only in APPROVED. Set status=FINAL, log "FINALIZED:v<version>"
    // 5. action="REJECT": only in REVIEW. Clear approvers, set status=DRAFT, log "REJECTED:<approver>"
    // 6. Invalid transitions return "INVALID"
    // 7. Success returns "OK"
    static String processAction(String action, String approver, String newContent) {

golden_completion:
if (action.equals("EDIT")) {
    if (!status.equals("DRAFT")) return "INVALID";
    content = newContent; version++;
    auditLog.add("EDIT:v" + version);
} else if (action.equals("SUBMIT")) {
    if (!status.equals("DRAFT")) return "INVALID";
    status = "REVIEW"; auditLog.add("SUBMITTED:v" + version);
} else if (action.equals("APPROVE")) {
    if (!status.equals("REVIEW")) return "INVALID";
    if (!approvers.contains(approver)) approvers.add(approver);
    if (approvers.size() >= requiredApprovals) status = "APPROVED";
    auditLog.add("APPROVE:" + approver + ":" + approvers.size() + "/" + requiredApprovals);
} else if (action.equals("FINALIZE")) {
    if (!status.equals("APPROVED")) return "INVALID";
    status = "FINAL"; auditLog.add("FINALIZED:v" + version);
} else if (action.equals("REJECT")) {
    if (!status.equals("REVIEW")) return "INVALID";
    approvers.clear(); status = "DRAFT"; auditLog.add("REJECTED:" + approver);
} else { return "INVALID"; }
return "OK";

suffix:
    }

