        return "OK";

    case "SUBMIT":
        if (!status.equals("DRAFT")) {
            return "INVALID";
        }
        status = "REVIEW";
        auditLog.add("SUBMITTED:v" + version);
        return "OK";

    case "APPROVE":
        if (!status.equals("REVIEW")) {
            return "INVALID";
        }
        if (!approvers.contains(approver)) {
            approvers.add(approver);
        }
        auditLog.add("APPROVE:" + approver + ":" + approvers.size() + "/" + requiredApprovals);
        if (approvers.size() >= requiredApprovals) {
            status = "APPROVED";
        }
        return "OK";

    case "FINALIZE":
        if (!status.equals("APPROVED")) {
            return "INVALID";
        }
        status = "FINAL";
        auditLog.add("FINALIZED:v" + version);
        return "OK";

    case "REJECT":
        if (!status.equals("REVIEW")) {
            return "INVALID";
        }
        approvers.clear();
        status = "DRAFT";
        auditLog.add("REJECTED:" + approver);
        return "OK";

    default:
        return "INVALID";
}

