import java.math.RoundingMode;
import java.util.*;

public class CPTask37 {
    static BigDecimal lastActualReading;
    static BigDecimal lastBilledReading;
    static BigDecimal estimatedUsage;
    static BigDecimal totalBilled;
    static BigDecimal tier1Limit = new BigDecimal("500");
    static BigDecimal tier1Rate = new BigDecimal("0.10");
    static BigDecimal tier2Rate = new BigDecimal("0.15");
    static List<String> auditLog;
    static int estimateCount;
    static int maxConsecutiveEstimates = 2;

    static void init() {
        lastActualReading = BigDecimal.ZERO;
        lastBilledReading = BigDecimal.ZERO;
        estimatedUsage = BigDecimal.ZERO;
        totalBilled = BigDecimal.ZERO;
        auditLog = new ArrayList<>();
        estimateCount = 0;
    }

    static BigDecimal calculateBill(BigDecimal usage) {
        if (usage.compareTo(tier1Limit) <= 0) {
            return usage.multiply(tier1Rate).setScale(2, RoundingMode.HALF_UP);
        }
        BigDecimal tier1 = tier1Limit.multiply(tier1Rate);
        BigDecimal tier2 = usage.subtract(tier1Limit).multiply(tier2Rate);
        return tier1.add(tier2).setScale(2, RoundingMode.HALF_UP);
    }

