    //       log "ADJUST:<adjustment>:BILL:<adjustBill>", reset estimatedUsage=0
    //    c. If estimatedUsage was 0: bill actualUsage normally
    //    d. Update lastActualReading = reading, lastBilledReading = reading, estimateCount = 0
    //    e. Log "ACTUAL:<reading>:USAGE:<actualUsage>"
    // 3. Return totalBilled
    static BigDecimal recordReading(BigDecimal reading, boolean estimated) {

