    BigDecimal usage = reading.subtract(lastBilledReading);
    estimatedUsage = estimatedUsage.add(usage); estimateCount++;
    BigDecimal bill = calculateBill(usage); totalBilled = totalBilled.add(bill);
    lastBilledReading = reading;
