public class CPTask38 {
    static BigDecimal gridRate = new BigDecimal("0.12");
    static BigDecimal solarCreditRate = new BigDecimal("0.08");
    static BigDecimal creditBalance;
    static BigDecimal maxMonthlyCredit = new BigDecimal("50.00");
    static BigDecimal totalPaid;
    static List<String> auditLog;

    static void init() {
        creditBalance = BigDecimal.ZERO;
        totalPaid = BigDecimal.ZERO;
        auditLog = new ArrayList<>();
    }

    // Process monthly billing. Rules:
    // 1. gridCost = consumedKWh * gridRate (scale 2, HALF_UP)
    // 2. solarCredit = exportedKWh * solarCreditRate (scale 2, HALF_UP)
    // 3. Cap solarCredit at maxMonthlyCredit: effectiveCredit = min(solarCredit, maxMonthlyCredit)
    // 4. Excess credit (solarCredit - effectiveCredit) rolls into creditBalance
    // 5. availableCredit = effectiveCredit + creditBalance
    // 6. If availableCredit >= gridCost:
    //    - payment = 0, creditBalance = availableCredit - gridCost
    //    - Log "CREDIT_COVERED:REMAINING:<creditBalance>"
    // 7. If availableCredit < gridCost:
    //    - payment = gridCost - availableCredit, creditBalance = 0
    //    - totalPaid += payment, Log "BILLED:<payment>"
    // 8. Return payment amount for this month
    static BigDecimal processBilling(BigDecimal consumedKWh, BigDecimal exportedKWh) {

golden_completion:
