BigDecimal solarCredit = exportedKWh.multiply(solarCreditRate).setScale(2, RoundingMode.HALF_UP);
BigDecimal effectiveCredit = solarCredit.min(maxMonthlyCredit);
BigDecimal excess = solarCredit.subtract(effectiveCredit);
creditBalance = creditBalance.add(excess);
BigDecimal availableCredit = effectiveCredit.add(creditBalance);
if (availableCredit.compareTo(gridCost) >= 0) {
    creditBalance = availableCredit.subtract(gridCost);
    auditLog.add("CREDIT_COVERED:REMAINING:" + creditBalance);
    return BigDecimal.ZERO;
}
BigDecimal payment = gridCost.subtract(availableCredit);
creditBalance = BigDecimal.ZERO;
totalPaid = totalPaid.add(payment);
auditLog.add("BILLED:" + payment);
return payment;

suffix:
    }

