    String finalName = ingredient;
    BigDecimal finalAmount = scaledAmount;
    if (substitutions.containsKey(ingredient)) {
        finalName = substitutions.get(ingredient);
        finalAmount = scaledAmount.multiply(substitutionRatios.get(finalName)).setScale(2, RoundingMode.HALF_UP);
    }
    if (finalAmount.compareTo(minAmount) < 0) finalAmount = minAmount;
    result.put(finalName, finalAmount);
    auditLog.add("SCALE:" + finalName + ":" + finalAmount);
}
