import java.math.BigDecimal;
import java.util.*;

public class CPTask41 {
    enum Tier { BRONZE, SILVER, GOLD, PLATINUM }

    static Map<String, Tier> passengerTiers = new HashMap<>();
    static Map<String, String> seatAssignments = new HashMap<>();
    static List<String> standbyQueue = new ArrayList<>();
    static Set<String> processedUpgrades = new HashSet<>();
    static List<String> auditLog = new ArrayList<>();

    // Upgrade rules:
    // 1. Only GOLD and PLATINUM can upgrade immediately; others go to standby
    // 2. If passenger already processed (idempotency), return "ALREADY_PROCESSED"
    // 3. Standby queue is ordered: SILVER before BRONZE, ties broken by request order
    // 4. Successful upgrade changes seat assignment and logs "UPGRADED:<passenger>:<newSeat>"
    // 5. Standby addition logs "STANDBY:<passenger>"
    static String requestUpgrade(String passenger, String newSeat) {

golden_completion:
if (processedUpgrades.contains(passenger)) {
    return "ALREADY_PROCESSED";
}
processedUpgrades.add(passenger);
Tier tier = passengerTiers.getOrDefault(passenger, Tier.BRONZE);
if (tier == Tier.GOLD || tier == Tier.PLATINUM) {
    seatAssignments.put(passenger, newSeat);
    auditLog.add("UPGRADED:" + passenger + ":" + newSeat);
    return "UPGRADED";
} else {
    // Insert SILVER before BRONZE in standby queue
    if (tier == Tier.SILVER) {
        int insertIdx = 0;
        for (int i = 0; i < standbyQueue.size(); i++) {
            Tier t = passengerTiers.getOrDefault(standbyQueue.get(i), Tier.BRONZE);
            if (t == Tier.SILVER) { insertIdx = i + 1; }
        }
        standbyQueue.add(insertIdx, passenger);
    } else {
        standbyQueue.add(passenger);
    }
    auditLog.add("STANDBY:" + passenger);
    return "STANDBY";
}

suffix:
    }

    public static void main(String[] args) {
        passengerTiers.put("Alice", Tier.PLATINUM);
        passengerTiers.put("Bob", Tier.BRONZE);
        passengerTiers.put("Carol", Tier.SILVER);

        assert requestUpgrade("Alice", "1A").equals("UPGRADED");
        assert seatAssignments.get("Alice").equals("1A");
        assert auditLog.get(0).equals("UPGRADED:Alice:1A");

        assert requestUpgrade("Bob", "2A").equals("STANDBY");
        assert requestUpgrade("Carol", "3A").equals("STANDBY");
        // Carol (SILVER) should be before Bob (BRONZE) in standby
        assert standbyQueue.get(0).equals("Carol");
        assert standbyQueue.get(1).equals("Bob");
    }
}

