public class CPTask42 {
    // Baggage fee rules:
    // 1. First bag free, 2nd bag $35, 3rd+ bag $75 each
    // 2. Overweight surcharge: bags > 50 lbs get $100 surcharge PER overweight bag
    // 3. Oversize surcharge: bags > 62 linear inches get $150 surcharge PER oversize bag
    // 4. Total fee capped at $500 per passenger (cumulative across all bags)
    // 5. Returns the fee charged for THIS bag (may be reduced by cap)
    // 6. Appends to feeLog: "BAG:<seq>:$<fee>" for each bag

    static List<String> feeLog = new ArrayList<>();
    static int bagCount = 0;
    static BigDecimal totalCharged = BigDecimal.ZERO;
    static final BigDecimal CAP = new BigDecimal("500");

    static BigDecimal checkBag(int weightLbs, int linearInches) {

