if (linearInches > 62) surcharge = surcharge.add(new BigDecimal("150"));
BigDecimal bagFee = baseFee.add(surcharge);
BigDecimal remaining = CAP.subtract(totalCharged);
if (remaining.compareTo(BigDecimal.ZERO) <= 0) {
    bagFee = BigDecimal.ZERO;
} else if (bagFee.compareTo(remaining) > 0) {
    bagFee = remaining;
}
totalCharged = totalCharged.add(bagFee);
