        PLAN_FEATURES.put(Plan.BUSINESS, Set.of("BASIC_REPORTS", "API_ACCESS", "SSO", "CUSTOM_DOMAINS"));
        PLAN_FEATURES.put(Plan.ENTERPRISE, Set.of("BASIC_REPORTS", "API_ACCESS", "SSO", "CUSTOM_DOMAINS", "AUDIT_LOG", "SLA"));
        SEAT_LIMITS.put(Plan.FREE, 3);
        SEAT_LIMITS.put(Plan.STARTER, 10);
        SEAT_LIMITS.put(Plan.BUSINESS, 50);
        SEAT_LIMITS.put(Plan.ENTERPRISE, Integer.MAX_VALUE);
        STORAGE_MB.put(Plan.FREE, 500);
        STORAGE_MB.put(Plan.STARTER, 5000);
        STORAGE_MB.put(Plan.BUSINESS, 50000);
        STORAGE_MB.put(Plan.ENTERPRISE, Integer.MAX_VALUE);
    }

