    static int currentSeats = 1;
    static int currentStorageMB = 0;
    static boolean trialActive = false;
    static int trialExpiryDay = -1;
    static boolean trialUsed = false;
    static List<String> provisionLog = new ArrayList<>();

    static void expireTrialIfNeeded(int currentDay) {
        if (trialActive && currentDay > trialExpiryDay) {
            trialActive = false;
            provisionLog.add("TRIAL_EXPIRED:" + currentDay);
        }
    }

    static String addSeat(int currentDay) {
        expireTrialIfNeeded(currentDay);
        int limit = SEAT_LIMITS.get(currentPlan);
        if (currentSeats >= limit) { provisionLog.add("DENIED:SEAT:" + currentDay); return "SEAT_LIMIT_REACHED"; }
        currentSeats++;
        provisionLog.add("SEAT_ADDED:" + currentSeats + ":" + currentDay);
        return "OK";
    }

    static String useStorage(int mb, int currentDay) {
        expireTrialIfNeeded(currentDay);
        int limit = STORAGE_MB.get(currentPlan);
        if (currentStorageMB + mb > limit) { provisionLog.add("DENIED:STORAGE:" + currentDay); return "STORAGE_EXCEEDED"; }
        currentStorageMB += mb;
        provisionLog.add("STORAGE:" + currentStorageMB + "MB:" + currentDay);
        return "OK";
    }

    // Provision action: processes a request by type
    // Actions: "ADD_SEAT", "USE_STORAGE:<mb>", "ACCESS:<feature>", "START_TRIAL"
    // Must check trial expiry on every call, respect plan gates, enforce one-shot trial
    static String provision(String action, int currentDay) {

golden_completion:
