if (action.equals("ADD_SEAT")) {
    return addSeat(currentDay);
} else if (action.startsWith("USE_STORAGE:")) {
    int mb = Integer.parseInt(action.split(":")[1]);
    return useStorage(mb, currentDay);
} else if (action.startsWith("ACCESS:")) {
    String feature = action.split(":")[1];
    Set<String> allowed = PLAN_FEATURES.get(currentPlan);
    if (allowed.contains(feature) || trialActive) return "GRANTED";
    return "FEATURE_LOCKED";
} else if (action.equals("START_TRIAL")) {
    if (trialUsed) return "TRIAL_EXHAUSTED";
    trialUsed = true;
    trialActive = true;
    trialExpiryDay = currentDay + 14;
    provisionLog.add("TRIAL_STARTED:" + currentDay);
    return "TRIAL_ACTIVE";
}
return "UNKNOWN_ACTION";

