import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask47 {
    // Corporate donation matching rules:
    // 1. Company matches employee donations at 1:1 ratio up to $500 per donation
    // 2. Annual corporate matching cap: $10,000 total across all employees
    // 3. Remaining annual budget tracked across calls
    // 4. Tax receipt: "RECEIPT:<employee>:personal=$<amt>:matched=$<matchAmt>:total=$<sum>"
    // 5. If annual cap already hit, match amount is $0 (personal donation still accepted)
    // 6. Partial match: if remaining budget < match (but > 0), match = remaining budget

    static BigDecimal annualBudgetRemaining = new BigDecimal("10000.00");
    static List<String> taxReceipts = new ArrayList<>();

    static BigDecimal processDonation(String employee, BigDecimal amount) {

golden_completion:
// Per-donation match cap: $500
BigDecimal maxMatch = new BigDecimal("500.00");
BigDecimal desiredMatch = amount.compareTo(maxMatch) > 0 ? maxMatch : amount;

// Apply annual budget constraint
BigDecimal actualMatch;
if (annualBudgetRemaining.compareTo(BigDecimal.ZERO) <= 0) {
    actualMatch = BigDecimal.ZERO;
} else if (desiredMatch.compareTo(annualBudgetRemaining) > 0) {
    actualMatch = annualBudgetRemaining;
} else {
    actualMatch = desiredMatch;
}
annualBudgetRemaining = annualBudgetRemaining.subtract(actualMatch);

BigDecimal total = amount.add(actualMatch).setScale(2, RoundingMode.HALF_UP);
taxReceipts.add("RECEIPT:" + employee + ":personal=$" + amount.setScale(2, RoundingMode.HALF_UP)
    + ":matched=$" + actualMatch.setScale(2, RoundingMode.HALF_UP)
    + ":total=$" + total);
return total;

suffix:
    }

    public static void main(String[] args) {
        // $300 donation — matched 1:1 ($300), total $600
        BigDecimal t1 = processDonation("Alice", new BigDecimal("300.00"));
        assert t1.compareTo(new BigDecimal("600.00")) == 0 : "t1=" + t1;

        // $800 donation — match capped at $500, total $1300
        BigDecimal t2 = processDonation("Bob", new BigDecimal("800.00"));
        assert t2.compareTo(new BigDecimal("1300.00")) == 0 : "t2=" + t2;

        assert taxReceipts.get(0).equals("RECEIPT:Alice:personal=$300.00:matched=$300.00:total=$600.00");
        assert taxReceipts.get(1).equals("RECEIPT:Bob:personal=$800.00:matched=$500.00:total=$1300.00");
    }
}

