import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask48 {
    // Grant disbursement rules:
    // 1. Grant has milestones (ordered list). Each has a percentage of total grant.
    // 2. Milestones must be completed IN ORDER — cannot skip ahead
    // 3. Each milestone releases its percentage, MINUS 10% holdback retained until final milestone
    // 4. When the LAST milestone is completed, the accumulated holdback is also released
    // 5. If a milestone is marked "FAILED", the grant enters CLAWBACK state:
    //    - No more disbursements allowed
    //    - Previously disbursed amounts remain (no actual clawback of money)
    //    - Holdback is forfeited (not released)
    // 6. Idempotency: completing same milestone twice returns "ALREADY_COMPLETED"

    static BigDecimal totalGrant = new BigDecimal("100000.00");
    static List<String> milestones = List.of("DESIGN", "PROTOTYPE", "PILOT", "SCALE");
    static List<Integer> milestonePcts = List.of(10, 25, 30, 35); // percentages
    static int nextMilestoneIdx = 0;
    static BigDecimal totalDisbursed = BigDecimal.ZERO;
    static BigDecimal holdback = BigDecimal.ZERO;
    static Set<String> completedMilestones = new LinkedHashSet<>();
    static String grantState = "ACTIVE";
    static List<String> disbursementLog = new ArrayList<>();

    static String completeMilestone(String milestone, boolean passed) {

golden_completion:
if (grantState.equals("CLAWBACK")) return "GRANT_CLAWBACK";
if (completedMilestones.contains(milestone)) return "ALREADY_COMPLETED";
if (nextMilestoneIdx >= milestones.size() || !milestones.get(nextMilestoneIdx).equals(milestone))
    return "WRONG_SEQUENCE";
if (!passed) {
    grantState = "CLAWBACK";
    disbursementLog.add("FAILED:" + milestone + ":holdback_forfeited=$" + holdback.setScale(2, RoundingMode.HALF_UP));
    return "MILESTONE_FAILED";
}
completedMilestones.add(milestone);
BigDecimal amt = totalGrant.multiply(new BigDecimal(milestonePcts.get(nextMilestoneIdx)))
    .divide(new BigDecimal("100"), 2, RoundingMode.HALF_UP);
boolean isLast = (nextMilestoneIdx == milestones.size() - 1);
BigDecimal disb = isLast ? amt.add(holdback) : amt.subtract(amt.multiply(new BigDecimal("0.10")).setScale(2, RoundingMode.HALF_UP));
if (isLast) { holdback = BigDecimal.ZERO; } else { holdback = holdback.add(amt.multiply(new BigDecimal("0.10")).setScale(2, RoundingMode.HALF_UP)); }
totalDisbursed = totalDisbursed.add(disb);
disbursementLog.add("DISBURSED:" + milestone + ":$" + disb.setScale(2, RoundingMode.HALF_UP));
nextMilestoneIdx++;
return "DISBURSED";

suffix:
    }

    public static void main(String[] args) {
        // DESIGN: 10% of 100k = 10000, holdback 10% = 1000, disbursed = 9000
