import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask50 {
    // Player contract rules:
    // 1. Base salary: paid each season via recordSeason()
    // 2. Performance bonuses (tiered):
    //    - 10+ goals: $100K bonus
    //    - 20+ goals: additional $200K (total $300K with tier 1)
    //    - 30+ goals: additional $500K (total $800K with tiers 1+2)
    // 3. Total bonus cap per season: $600K (so 30+ goals gets $600K, not $800K)
    // 4. Injury clause: if gamesPlayed < 10, no bonus regardless of goals (player was injured)
    //    BUT base salary is still paid at 50% (injury deduction)
    // 5. Vesting: first 2 seasons are "probation" — bonuses are held in escrow,
    //    released only when season 3 starts (vesting event). If player leaves before
    //    season 3, escrowed bonuses are forfeited.

    static BigDecimal baseSalary = new BigDecimal("2000000.00"); // $2M
    static int currentSeason = 0;
    static BigDecimal totalPaid = BigDecimal.ZERO;
    static BigDecimal escrow = BigDecimal.ZERO;
    static boolean vested = false;
    static List<String> payLog = new ArrayList<>();
    static final BigDecimal BONUS_CAP = new BigDecimal("600000");

    // Calculate raw tiered bonus (before cap): 10+=100K, 20+=+200K, 30+=+500K
    static BigDecimal rawBonus(int goals) {
        BigDecimal b = BigDecimal.ZERO;
        if (goals >= 10) b = b.add(new BigDecimal("100000"));
        if (goals >= 20) b = b.add(new BigDecimal("200000"));
        if (goals >= 30) b = b.add(new BigDecimal("500000"));
        return b.compareTo(BONUS_CAP) > 0 ? BONUS_CAP : b;
    }

    static String recordSeason(int goals, int gamesPlayed) {

golden_completion:
currentSeason++;
BigDecimal salary, bonus = BigDecimal.ZERO;
if (gamesPlayed < 10) {
    salary = baseSalary.multiply(new BigDecimal("0.50"));
    payLog.add("SEASON:" + currentSeason + ":salary=$" + salary.setScale(2, RoundingMode.HALF_UP) + ":bonus=$0.00:injury=true");
} else {
    salary = baseSalary;
    bonus = rawBonus(goals);
    if (currentSeason <= 2 && !vested) {
        escrow = escrow.add(bonus);
        payLog.add("SEASON:" + currentSeason + ":salary=$" + salary.setScale(2, RoundingMode.HALF_UP) + ":bonus=$" + bonus.setScale(2, RoundingMode.HALF_UP) + ":escrowed=true");
        bonus = BigDecimal.ZERO;
    } else {
        if (!vested && currentSeason == 3) { vested = true; bonus = bonus.add(escrow); escrow = BigDecimal.ZERO; }
        payLog.add("SEASON:" + currentSeason + ":salary=$" + salary.setScale(2, RoundingMode.HALF_UP) + ":bonus=$" + bonus.setScale(2, RoundingMode.HALF_UP) + ":escrowed=false");
    }
}
totalPaid = totalPaid.add(salary).add(bonus);
return "SEASON_" + currentSeason + "_COMPLETE";

suffix:
    }

    public static void main(String[] args) {
        // Season 1: 15 goals, 30 games — $100K bonus but escrowed
        recordSeason(15, 30);
        // Paid: $2M salary only (bonus escrowed)
        assert totalPaid.compareTo(new BigDecimal("2000000.00")) == 0 : "S1 paid: " + totalPaid;
        assert escrow.compareTo(new BigDecimal("100000.00")) == 0 : "S1 escrow: " + escrow;

        // Season 2: 25 goals, 35 games — $300K bonus but escrowed
        recordSeason(25, 35);
        assert totalPaid.compareTo(new BigDecimal("4000000.00")) == 0 : "S2 paid: " + totalPaid;
        assert escrow.compareTo(new BigDecimal("400000.00")) == 0 : "S2 escrow: " + escrow;

        // Season 3: 22 goals, 38 games — $300K bonus + escrow release ($400K) = $700K paid
        recordSeason(22, 38);
        assert vested : "Should be vested after season 3";
        // S3: 2M + 300K + 400K escrow = 2.7M; total = 4M + 2.7M = 6.7M
        assert totalPaid.compareTo(new BigDecimal("6700000.00")) == 0 : "S3 total: " + totalPaid;
    }
}

